($$nossa-senhora-dores$$, $$Nossa Senhora das Dores$$, $$Mater Dolorosa$$, $$15 de Setembro$$, 9, 15, $$$$, $$$$, '{"Aflitos"}'::text[], $$Memória das sete dores de Maria: a profecia de Simeão, a fuga ao Egito, a perda de Jesus no Templo, o encontro na Via Crucis, a crucificação, a deposição e a sepultura.$$, $$Memória das sete dores de Maria: a profecia de Simeão, a fuga ao Egito, a perda de Jesus no Templo, o encontro na Via Crucis, a crucificação, a deposição e a sepultura.$$, $$[]$$::jsonb, '{"\"Uma espada traspassará a tua alma.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Mater_Dolorosa_by_Carlo_Dolci.jpg/440px-Mater_Dolorosa_by_Carlo_Dolci.jpg$$, $$$$, '{"Compaixão","Sofrimento"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$mateus$$, $$São Mateus$$, $$Apóstolo e Evangelista$$, $$21 de Setembro$$, 9, 21, $$Séc. I, Cafarnaum$$, $$Séc. I, Etiópia$$, '{"Contadores","Banqueiros"}'::text[], $$Publicano chamado por Jesus, autor do primeiro Evangelho. Pregou na Etiópia.$$, $$Publicano chamado por Jesus, autor do primeiro Evangelho. Pregou na Etiópia.$$, $$[]$$::jsonb, '{"\"Segue-me! E ele se levantou e o seguiu.\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Caravaggio_-_The_Calling_of_Saint_Matthew.jpg/440px-Caravaggio_-_The_Calling_of_Saint_Matthew.jpg$$, $$$$, '{"Conversão","Obediência"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
