($$anjos-guarda$$, $$Santos Anjos da Guarda$$, $$Protetores Celestes$$, $$2 de Outubro$$, 10, 2, $$$$, $$$$, '{"Crianças","Vigilantes"}'::text[], $$Festa que celebra os anjos designados por Deus para guardar e proteger cada pessoa.$$, $$Festa que celebra os anjos designados por Deus para guardar e proteger cada pessoa.$$, $$[]$$::jsonb, '{"\"Ele enviará seus anjos para te guardar em todos os teus caminhos.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Bernardo_Strozzi_-_Guardian_Angel.jpg/440px-Bernardo_Strozzi_-_Guardian_Angel.jpg$$, $$$$, '{"Proteção"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$nossa-senhora-rosario$$, $$Nossa Senhora do Rosário$$, $$Rainha do Santo Rosário$$, $$7 de Outubro$$, 10, 7, $$$$, $$$$, '{"Rosário"}'::text[], $$Festa instituída após a victory de Lepanto em 1571, atribuída à intercessão de Nossa Senhora do Rosário.$$, $$Festa instituída após a victory de Lepanto em 1571, atribuída à intercessão de Nossa Senhora do Rosário.$$, $$[]$$::jsonb, '{"\"Rezai o Rosário todos os dias.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Bartolom%C3%A9_Esteban_Murillo_-_Our_Lady_of_the_Rosary_-_Google_Art_Project.jpg/440px-Bartolom%C3%A9_Esteban_Murillo_-_Our_Lady_of_the_Rosary_-_Google_Art_Project.jpg$$, $$$$, '{"Oração","Meditação"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
